import * as THREE from 'three';
export function capturePanorama(studio,position,{floor,ceilingHeight=2.7}={}){const r=studio.renderer,size=r.getSize(new THREE.Vector2()),ratio=r.getPixelRatio(),target=r.getRenderTarget(),bg=studio.scene.background,hidden=[];const cube=new THREE.WebGLCubeRenderTarget(512,{type:THREE.HalfFloatType}),cam=new THREE.CubeCamera(.05,250,cube),s=new THREE.Scene(),camera=new THREE.OrthographicCamera(-1,1,1,-1,0,1),material=new THREE.ShaderMaterial({uniforms:{map:{value:cube.texture}},vertexShader:'varying vec2 uvp;void main(){uvp=uv;gl_Position=vec4(position.xy,0.,1.);}',fragmentShader:'uniform samplerCube map;varying vec2 uvp;void main(){float lon=(uvp.x-.5)*6.283185307;float lat=(uvp.y-.5)*3.141592654;vec3 dir=vec3(sin(lon)*cos(lat),sin(lat),-cos(lon)*cos(lat));gl_FragColor=textureCube(map,dir);\n#include <tonemapping_fragment>\n#include <colorspace_fragment>\n}'}),quad=new THREE.Mesh(new THREE.PlaneGeometry(2,2),material);s.add(quad);
 const roofs=new THREE.Group();if(floor)for(const room of floor.rooms){const roof=new THREE.Mesh(new THREE.PlaneGeometry(room.w,room.d),new THREE.MeshStandardMaterial({color:'#f5f0e8',side:THREE.DoubleSide}));roof.rotation.x=Math.PI/2;roof.position.set(room.x+room.w/2,ceilingHeight,room.z+room.d/2);roofs.add(roof);}studio.content.add(roofs);
 try{for(const o of studio.scene.children)if(o!==studio.content&&!o.isLight&&!o.name.startsWith('Walk')){hidden.push([o,o.visible]);o.visible=false;}studio.scene.background=new THREE.Color('#e5e0d6');cam.position.fromArray(position);cam.update(r,studio.scene);r.setRenderTarget(null);r.setPixelRatio(1);r.setSize(2048,1024,false);r.render(s,camera);return studio.canvas.toDataURL('image/png');}finally{roofs.removeFromParent();roofs.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});for(const [o,v]of hidden)o.visible=v;cube.dispose();quad.geometry.dispose();material.dispose();studio.scene.background=bg;r.setPixelRatio(ratio);r.setSize(size.x,size.y,false);r.setRenderTarget(target);}
}
export function sphericalViewer(canvas,url,{hotspots=[],onNavigate=()=>{}}={}){const renderer=new THREE.WebGLRenderer({canvas,antialias:true}),scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(75,1,.01,20),texture=new THREE.TextureLoader().load(url);texture.colorSpace=THREE.SRGBColorSpace;texture.wrapS=THREE.RepeatWrapping;texture.repeat.x=-1;texture.offset.x=1.25;const mesh=new THREE.Mesh(new THREE.SphereGeometry(10,64,32),new THREE.MeshBasicMaterial({map:texture,side:THREE.BackSide}));scene.add(mesh);let yaw=0,pitch=0,drag=null,frame;const parent=canvas.parentElement,buttons=hotspots.map(h=>{const button=document.createElement('button');button.className='panorama-hotspot';button.textContent='↗ '+h.label;button.onclick=()=>onNavigate(h.roomId);parent.append(button);return {button,...h};});const resize=()=>{const rect=canvas.getBoundingClientRect();renderer.setSize(rect.width,rect.height,false);camera.aspect=rect.width/rect.height;camera.updateProjectionMatrix();};const observer=new ResizeObserver(resize);observer.observe(canvas);canvas.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,yaw,pitch};canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(drag){yaw=drag.yaw-(e.clientX-drag.x)*.005;pitch=Math.max(-1.45,Math.min(1.45,drag.pitch+(e.clientY-drag.y)*.005));}};canvas.onpointerup=()=>drag=null;canvas.onpointercancel=()=>drag=null;canvas.onwheel=e=>{e.preventDefault();camera.fov=Math.max(35,Math.min(100,camera.fov+e.deltaY*.03));camera.updateProjectionMatrix();};function draw(){camera.rotation.order='YXZ';camera.rotation.set(pitch,yaw,0);renderer.render(scene,camera);for(const h of buttons){const point=new THREE.Vector3(h.dx,0,h.dz).normalize().multiplyScalar(5),forward=new THREE.Vector3();camera.getWorldDirection(forward);h.button.hidden=point.dot(forward)<0;point.project(camera);h.button.style.left=(point.x*.5+.5)*canvas.clientWidth+'px';h.button.style.top=(-point.y*.5+.5)*canvas.clientHeight+'px';}frame=requestAnimationFrame(draw);}resize();draw();return ()=>{cancelAnimationFrame(frame);observer.disconnect();for(const h of buttons)h.button.remove();texture.dispose();mesh.geometry.dispose();mesh.material.dispose();renderer.dispose();};}
